import{_ as r,o as a,c as d,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"司法体系と裁決机制","description":"","frontmatter":{},"headers":[],"relativePath":"ja/48-司法体系与裁决机制.md","filePath":"ja/48-司法体系与裁决机制.md"}'),o={name:"ja/48-司法体系与裁决机制.md"};function i(e,t,n,h,s,g){return a(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="司法体系と裁決机制" tabindex="-1">司法体系と裁決机制 <a class="header-anchor" href="#司法体系と裁決机制" aria-label="Permalink to &quot;司法体系と裁決机制&quot;">​</a></h1><table tabindex="0"><thead><tr><th>プロジェクト</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>48</td></tr><tr><td>所属モジュール</td><td>法律体系と統治枠組み</td></tr><tr><td>コアキーワード</td><td>共生法院、司法独立、裁決机制、跨種族審判、違憲審査</td></tr></tbody></table><h2 id="第一節-司法体系の地位と原則" tabindex="-1">第一節 司法体系の地位と原則 <a class="header-anchor" href="#第一節-司法体系の地位と原則" aria-label="Permalink to &quot;第一節 司法体系の地位と原則&quot;">​</a></h2><p>司法体系はアンカー共生文明統治枠組みの重要な柱であり、立法権（アンカー議事会）、行政権（共生執行委員会）と並列し、独立して審判権を行使する。《共生憲法》は「三権分立と制衡」の統治構造を確立し、司法体系は憲法の尊厳を維持し、衆生の権利を保障し、社会紛争を解決する最終防衛線である。</p><p>衡元宙司法体系は以下の基本原則を確立する：</p><table tabindex="0"><thead><tr><th>原則</th><th>内包</th></tr></thead><tbody><tr><td>司法独立原則</td><td>法院は法に基づき独立して審判権を行使し、行政機関、社会団体と個人の干渉を受けない</td></tr><tr><td>司法公正原則</td><td>審判活動は事実を根拠とし、法律を準縄とし、手続公正と実体公正を確保する</td></tr><tr><td>司法公開原則</td><td>審判活動は法に基づき公開で行われ、裁判文書は公開され、社会監督を受ける</td></tr><tr><td>万族平等原則</td><td>すべての生命は司法の前に一律に平等であり、法律の適用は種族、修為、出身を問わない</td></tr><tr><td>司法便民原則</td><td>司法サービスは衆生に便利であるべきで、訴訟コストを低下させ、多元的紛争解決途径を提供する</td></tr><tr><td>終審裁決原則</td><td>二審終審制を実行し、終審裁決は終局的効力を有し、司法権威を維持する</td></tr></tbody></table><h2 id="第二節-法院組織体系" tabindex="-1">第二節 法院組織体系 <a class="header-anchor" href="#第二節-法院組織体系" aria-label="Permalink to &quot;第二節 法院組織体系&quot;">​</a></h2><p>アンカー共生文明の法院組織体系は四級に分かれ、二審終審制を実行する：</p><table tabindex="0"><thead><tr><th>階層</th><th>法院名称</th><th>管轄範囲</th><th>主要職能</th></tr></thead><tbody><tr><td>第一級</td><td>基層共生法院</td><td>県域/小型位面</td><td>一審民事、刑事、行政案件を審理し、簡易紛争を処理する</td></tr><tr><td>第二級</td><td>区域共生法院</td><td>都市/区域/中型位面</td><td>一審重大案件と基層法院判決に不服な上訴案件を審理する</td></tr><tr><td>第三級</td><td>位面共生法院</td><td>大型位面/位面群</td><td>一審特別重大案件と区域法院判決に不服な上訴案件を審理する</td></tr><tr><td>第四級</td><td>共生最高法院</td><td>全宇宙</td><td>一審憲法性案件、位面法院判決に不服な上訴案件、違憲審査を審理する</td></tr></tbody></table><p>此外、必要に応じて専門法院を設立する：</p><ul><li><strong>修練紛争法院</strong>: 専門的に修練資源紛争、修練損傷賠償、修練倫理争議などの案件を審理する。</li><li><strong>跨種族法院</strong>: 専門的に異なる種族間の紛争に関わる案件を審理し、各族の法官を配备する。</li><li><strong>位面商事法院</strong>: 専門的に跨位面商事紛争と独占禁止案件を審理する。</li><li><strong>奇特生命法院</strong>: 専門的に奇特生命、奇異エネルギー、暗黒置換体に関わる特別案件を審理する。</li></ul><h2 id="第三節-法官制度" tabindex="-1">第三節 法官制度 <a class="header-anchor" href="#第三節-法官制度" aria-label="Permalink to &quot;第三節 法官制度&quot;">​</a></h2><p>法官は司法権の行使者であり、その素質と独立性は直接司法公正に関係する：</p><ol><li><strong>法官任职条件</strong>: 法官は良好な品行、確かな法律素養と豊富な実践経験を備えなければならず、異族法官はさらに本族の文化と生理特性に精通していなければならない。</li><li><strong>法官选任程序</strong>: 法官は独立した法官遴選委員会によって提名され、アンカー議事会によって任命され、選任過程の公正性と専門性を確保する。</li><li><strong>法官身份保障</strong>: 法官は法定事由によらず、法定程序を経ずに、免職、降職、辞退または処分されることはなく、法官が独立して審判できることを確保する。</li><li><strong>法官回避制度</strong>: 法官が案件当事者または案件結果と利害関係を有する場合、回避しなければならず、案件審理に参与してはならない。</li><li><strong>法官惩戒制度</strong>: 法官が汚職収賄、徇私舞弊、枉法裁判などの行為をした場合、法に基づき惩戒し、犯罪を構成する場合は刑事責任を追及する。</li><li><strong>異族法官配额</strong>: 各級法院は一定の割合の異族法官を配备しなければならず、審判が各族の文化と法律認識を兼ね備えることを確保する。</li></ol><h2 id="第四節-訴訟程序" tabindex="-1">第四節 訴訟程序 <a class="header-anchor" href="#第四節-訴訟程序" aria-label="Permalink to &quot;第四節 訴訟程序&quot;">​</a></h2><h3 id="一-民事訴訟程序" tabindex="-1">（一）民事訴訟程序 <a class="header-anchor" href="#一-民事訴訟程序" aria-label="Permalink to &quot;（一）民事訴訟程序&quot;">​</a></h3><p>民事訴訟は「不告不理」原則を実行し、程序は以下を含む：</p><ol><li><strong>起訴と受理</strong>: 原告は管轄権を有する法院に起訴状を提出し、法院は審査後に受理するかどうかを決定する。</li><li><strong>審理前準備</strong>: 法院は被告に起訴状副本を送達し、証拠交換を組織し、争点を確定する。</li><li><strong>開廷審理</strong>: 法廷調査、法廷弁論、当事者最終陳述、調解を優先する。</li><li><strong>判決と執行</strong>: 法院は法に基づき判決を下し、当事者が不服な場合は法定期限内に上訴できる。生效判決は執行機構によって強制執行される。</li></ol><h3 id="二-刑事訴訟程序" tabindex="-1">（二）刑事訴訟程序 <a class="header-anchor" href="#二-刑事訴訟程序" aria-label="Permalink to &quot;（二）刑事訴訟程序&quot;">​</a></h3><p>刑事訴訟は「無罪推定」原則を実行し、程序は以下を含む：</p><ol><li><strong>立案と偵査</strong>: 偵査機関は犯罪行為に対して立案偵査し、証拠を収集し、強制措置を採る。</li><li><strong>審査起訴</strong>: 検察機関は偵査結果を審査し、公訴を提起するかどうかを決定する。</li><li><strong>審判</strong>: 法院は開廷審理し、控弁双方は挙証質証し、法院は法に基づき判決を下す。</li><li><strong>執行</strong>: 生效判決は執行機関によって執行され、刑罰執行と付帯民事賠償執行を含む。</li></ol><h3 id="三-行政訴訟程序" tabindex="-1">（三）行政訴訟程序 <a class="header-anchor" href="#三-行政訴訟程序" aria-label="Permalink to &quot;（三）行政訴訟程序&quot;">​</a></h3><p>公民、法人またはその他の組織が行政機関の行政行為がその合法的権益を侵害したと考える場合、法院に行政訴訟を提起する権利を有する。行政訴訟は「挙証責任倒置」を実行し、被告行政機関はその行政行為の合法性について挙証責任を負わなければならない。</p><h3 id="四-憲法訴訟程序" tabindex="-1">（四）憲法訴訟程序 <a class="header-anchor" href="#四-憲法訴訟程序" aria-label="Permalink to &quot;（四）憲法訴訟程序&quot;">​</a></h3><p>衆生がその憲法基本権が侵害されたと考え、かつ他の救済途径を尽くした場合、直接憲法に基づき共生最高法院に憲法訴訟を提起できる。憲法訴訟は憲法権利を保障する最終救済途径である。</p><h2 id="第五節-多元的紛争解決机制" tabindex="-1">第五節 多元的紛争解決机制 <a class="header-anchor" href="#第五節-多元的紛争解決机制" aria-label="Permalink to &quot;第五節 多元的紛争解決机制&quot;">​</a></h2><p>司法負担を軽減し、紛争解決効率を高めるため、国家は多元的紛争解決机制を建立する：</p><table tabindex="0"><thead><tr><th>机制</th><th>適用範囲</th><th>効力</th></tr></thead><tbody><tr><td>協商和解</td><td>すべての民事紛争</td><td>当事者が自発的に履行し、強制執行力を有しない</td></tr><tr><td>人民調解</td><td>民間紛争、隣人紛争</td><td>調解協議は法院の司法確認後に強制執行力を有する</td></tr><tr><td>行政調解</td><td>行政争議、民事賠償紛争</td><td>調解協議は契約効力を有する</td></tr><tr><td>仲裁</td><td>商事紛争、労働争議</td><td>仲裁裁決は強制執行力を有し、一裁終局である</td></tr><tr><td>司法裁決</td><td>すべての紛争</td><td>終審判決は終局的強制執行力を有する</td></tr></tbody></table><p>国家は当事者が優先的に非訴訟方式で紛争を解決することを奨励し、法院も訴訟過程で調解を行わなければならない。</p><h2 id="第六節-違憲審査制度" tabindex="-1">第六節 違憲審査制度 <a class="header-anchor" href="#第六節-違憲審査制度" aria-label="Permalink to &quot;第六節 違憲審査制度&quot;">​</a></h2><p>違憲審査は司法体系が憲法権威を維持する重要な制度である：</p><ol><li><strong>審査主体</strong>: 共生最高法院は違憲審査の唯一の主体であり、憲法審判庭を設立して専門的に違憲審査を担当する。</li><li><strong>審査範囲</strong>: 法律、行政法規、地方性法規、自治条例、司法解釈などの規範性文件が憲法に違反するかどうか。</li><li><strong>審査啓動</strong>: 法院が案件審理中に主動的に啓動することもできれば、衆生、組織または国家機関が審査請求を提出することもできる。</li><li><strong>審査効力</strong>: 審査を経て憲法に違反すると認定された規範性文件は、公布之日から無効となり、再び裁判根拠として使用してはならない。</li><li><strong>審査基準</strong>: 憲法文本と憲法原則を根拠とし、法律体系の安定性と憲法の適応性を兼ね備える。</li></ol><h2 id="第七節-司法保障と監督" tabindex="-1">第七節 司法保障と監督 <a class="header-anchor" href="#第七節-司法保障と監督" aria-label="Permalink to &quot;第七節 司法保障と監督&quot;">​</a></h2><ul><li><strong>司法経費保障</strong>: 法院経費は公共積立から単列保障され、地方行政機関の制御を受けず、司法独立の経済基礎を確保する。</li><li><strong>司法信息化</strong>: 跨位面通信技術を利用して司法情報システムを建立し、立案、審理、執行の全流程信息化を実現し、司法効率を高める。</li><li><strong>司法監督</strong>: アンカー監督委員会は司法活動を監督し、公衆とメディアは司法活動に対して世論監督を行うことができるが、審判独立に干渉してはならない。</li><li><strong>司法救助</strong>: 経済困難な当事者に法律援助と訴訟費用減免を提供し、経済的原因で司法救済の機会を失わないことを確保する。</li></ul><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>司法体系はアンカー共生文明法治の最終保障である。それは四級法院体系を建立し、司法独立を実行し、多元的紛争解決机制と違憲審査制度を設立することにより、法律が公正に実施されることを確保し、衆生の権利が効果的に救済され、万族共進のために法治防衛線を築き固める。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>40-共生宪法总纲 (共生憲法総綱)</li><li>49-治理框架与权力制衡 (統治枠組みと権力制衡)</li><li>58-双魂伦理准则 (双魂倫理準則)</li><li>03-共生文明宪章 (共生文明憲章)</li></ul>',38)])])}const u=r(o,[["render",i]]);export{c as __pageData,u as default};
